"const WebSocket = global.WebSocket || require('ws');

async function main() {
  const res = await fetch('http://192.168.1.15:9998/json');
  const pages = await res.json();
  const poc = pages.find(p => p.url && p.url.includes('com.cinejoy.poc'));
  console.log('PoC Page:', poc.title, poc.url);

  const ws = new WebSocket(poc.webSocketDebuggerUrl);
  await new Promise(r => ws.on('open', r));

  let id = 1;
  function evaluate(expr) {
    return new Promise((resolve, reject) => {
      const msgId = id++;
      const handler = (data) => {
        const msg = JSON.parse(data);
        if (msg.id === msgId) {
          ws.off('message', handler);
          if (msg.error) reject(new Error(msg.error.message));
          else resolve(msg.result && msg.result.result ? msg.result.result.value : msg.result);
        }
      };
      ws.on('message', handler);
      ws.send(JSON.stringify({
        id: msgId,
        method: 'Runtime.evaluate',
        params: { expression: expr, returnByValue: true }
      }));
    });
  }

  const vState = await evaluate(`(() => {
    const v = document.getElementById("poc-video");
    return {
      src: v.src,
      currentSrc: v.currentSrc,
      currentTime: v.currentTime,
      duration: v.duration,
      paused: v.paused,
      ended: v.ended,
      readyState: v.readyState,
      networkState: v.networkState,
      videoWidth: v.videoWidth,
      videoHeight: v.videoHeight,
      error: v.error ? { code: v.error.code, message: v.error.message } : null,
      bufferedRanges: v.buffered ? Array.from({length: v.buffered.length}, (_, i) => [v.buffered.start(i), v.buffered.end(i)]) : []
    };
  })()`);

  console.log('Video State:', JSON.stringify(vState, null, 2));
  ws.close();
}

main().catch(console.error);
"

"const WebSocket = global.WebSocket;

async function main() {
  const res = await fetch('http://192.168.1.15:9998/json');
  const pages = await res.json();
  const poc = pages.find(p => p.url && p.url.includes('com.cinejoy.poc'));
  console.log('PoC Page:', poc.title, poc.url);

  const ws = new WebSocket(poc.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => {
    ws.onopen = resolve;
    ws.onerror = reject;
  });

  let id = 1;
  const pending = new Map();
  ws.onmessage = (event) => {
    const msg = JSON.parse(event.data);
    if (msg.id && pending.has(msg.id)) {
      const { resolve, reject } = pending.get(msg.id);
      pending.delete(msg.id);
      if (msg.error) reject(new Error(msg.error.message));
      else resolve(msg.result && msg.result.result ? msg.result.result.value : msg.result);
    }
  };

  function evaluate(expr) {
    return new Promise((resolve, reject) => {
      const msgId = id++;
      pending.set(msgId, { resolve, reject });
      ws.send(JSON.stringify({
        id: msgId,
        method: 'Runtime.evaluate',
        params: { expression: expr, returnByValue: true, awaitPromise: true }
      }));
    });
  }

  const vState = await evaluate(`(() => {
    const v = document.getElementById("poc-video");
    return {
      src: v.src,
      currentSrc: v.currentSrc,
      currentTime: v.currentTime,
      duration: v.duration,
      paused: v.paused,
      ended: v.ended,
      readyState: v.readyState,
      networkState: v.networkState,
      videoWidth: v.videoWidth,
      videoHeight: v.videoHeight,
      error: v.error ? { code: v.error.code, message: v.error.message } : null,
      bufferedRanges: v.buffered ? Array.from({length: v.buffered.length}, (_, i) => [v.buffered.start(i), v.buffered.end(i)]) : []
    };
  })()`);

  console.log('Video State:', JSON.stringify(vState, null, 2));
  ws.close();
}

main().catch(console.error);
"

