"const WebSocket = global.WebSocket;

async function main() {
  const res = await fetch('http://192.168.1.15:9998/json');
  const pages = await res.json();
  const poc = pages.find(p => p.url && p.url.includes('com.cinejoy.poc'));

  const ws = new WebSocket(poc.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => {
    ws.onopen = resolve;
    ws.onerror = reject;
  });

  let id = 1;
  const pending = new Map();
  ws.onmessage = (event) => {
    const msg = JSON.parse(event.data);
    if (msg.id && pending.has(msg.id)) {
      const { resolve, reject } = pending.get(msg.id);
      pending.delete(msg.id);
      if (msg.error) reject(new Error(msg.error.message));
      else resolve(msg.result && msg.result.result ? msg.result.result.value : msg.result);
    }
  };

  function evaluate(expr) {
    return new Promise((resolve, reject) => {
      const msgId = id++;
      pending.set(msgId, { resolve, reject });
      ws.send(JSON.stringify({
        id: msgId,
        method: 'Runtime.evaluate',
        params: { expression: expr, returnByValue: true, awaitPromise: true }
      }));
    });
  }

  console.log('Calling reloadStream()...');
  await evaluate('reloadStream()');

  for (let i = 0; i < 15; i++) {
    await new Promise(r => setTimeout(r, 1000));
    const st = await evaluate(`(() => {
      const v = document.getElementById("poc-video");
      return {
        src: v.src,
        currentTime: v.currentTime,
        readyState: v.readyState,
        paused: v.paused,
        networkState: v.networkState,
        error: v.error ? { code: v.error.code, message: v.error.message } : null
      };
    })()`);
    console.log(`[T+${i+1}s]`, JSON.stringify(st));
    if (st.readyState >= 3) {
      console.log('RELOAD STREAM SUCCESS! readyState >= 3');
      break;
    }
  }

  ws.close();
}

main().catch(console.error);
"

